onClick:
{{
  Insert_Intervention.run()
    .then((resultat) => {
      // 1. Affiche un message de succès
      showAlert('Intervention créée avec succès !', 'success');

      // 2. Ferme la fenêtre modale
      closeModal('modal_add_intervention');

      // 3. Rafraîchit le tableau principal (optionnel, mais utile en arrière-plan)
      Get_Atelier_Global.run();

      // 4. Ouvre la page de détail
      // Vérifie bien que "Détail Intervention" est le nom exact de ta page
      if (resultat && resultat.length > 0 && resultat[0].ID_Intervention) {
          navigateTo('Détail Intervention', { id: resultat[0].ID_Intervention });
      } else {
          showAlert("Intervention créée, mais impossible d'ouvrir le détail. ID introuvable.", "warning");
      }
    })
    .catch((error) => {
      // En cas d'erreur
      showAlert("Erreur lors de l'enregistrement. Vérifie les champs.", "error");
      console.error(error);
    });
}}
